if (!root) root = std::make_shared<Node>();
while (true) {
    char symbol;
    infile.read(reinterpret_cast<char*>(&symbol), sizeof(symbol));
    if (infile.eof()) break;
    std::uint8_t code_len;
    infile.read(reinterpret_cast<char*>(&code_len), sizeof(code_len));
    if (infile.eof()) break;
    std::size_t byte_cnt = (code_len + 7) / 8;
    std::vector<std::uint8_t> code_bytes(byte_cnt);
    if (byte_cnt > 0) {
        infile.read(reinterpret_cast<char*>(code_bytes.data()), byte_cnt);
        if (infile.gcount() != static_cast<std::streamsize>(byte_cnt)) break;
    }
    std::shared_ptr<Node> cur = root;
    for (std::uint8_t i = 0; i < code_len; ++i) {
        std::uint8_t byte_idx = i / 8;
        std::uint8_t bit_idx  = 7 - (i % 8);
        bool bit = (code_bytes[byte_idx] >> bit_idx) & 0x01;
        if (!bit) {
            if (!cur->left) cur->left = std::make_shared<Node>();
            cur = cur->left;
        } else {
            if (!cur->right) cur->right = std::make_shared<Node>();
            cur = cur->right;
        }
    }
    cur->ch = symbol;
    cur->isLeaf = true;
}

